fn is_ascii_digit(c: char) -> bool {
    // Check if the character is between '0' and '9'
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // An empty string is considered to have all characters as digits
    if s.is_empty() {
        return true;
    }

    // Check each character in the string
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false; // Return false if any character is not a digit
        }
    }

    true // All characters are digits
}

fn main() {
    // Example usage
    let test_char = '5';
    let test_string = String::from("12345");
    let test_empty_string = String::from("");

    println!("Is '{}' an ASCII digit? {}", test_char, is_ascii_digit(test_char)); // true
    println!("Are all characters in '{}' ASCII digits? {}", test_string, all_digits(test_string)); // true
    println!("Are all characters in '{}' ASCII digits? {}", test_empty_string, all_digits(test_empty_string)); // true
}